	@Test
	void warmedValidationKeepsAllFactoryCallsAcrossCollisionsAndLongIris() throws IOException {
		List<String> iris = new ArrayList<>();
		for (int i = 0; i < 40; i++) {
			iris.add("urn:warm");
		}
		for (int i = 0; i < 192; i++) {
			iris.add("urn:unique:" + i);
		}
		for (int i = 0; i < 192; i++) {
			StringBuilder collision = new StringBuilder("urn:collision:");
			for (int bit = 0; bit < 8; bit++) {
				collision.append((i & (1 << bit)) == 0 ? "Aa" : "BB");
			}
			String iri = collision.toString();
			assertEquals(("urn:collision:" + "Aa".repeat(8)).hashCode(), iri.hashCode());
			iris.add(iri);
		}
		String longIri = "urn:long:" + "a".repeat(4096);
		for (int i = 0; i < 40; i++) {
			iris.add(longIri);
		}
		for (int i = 0; i < 40; i++) {
			iris.add("urn:warm");
		}

		StringBuilder document = new StringBuilder();
		List<String> expectedCalls = new ArrayList<>();
		for (String iri : iris) {
			for (int position = 0; position < 4; position++) {
				document.append('<').append(iri).append("> ");
				expectedCalls.add("iri:" + iri);
			}
			document.append(".\n");
			expectedCalls.add("statement:4");
		}
		RecordingFactory factory = new RecordingFactory();
		NQuadsParser parser = new NQuadsParser(factory);
		parser.getParserConfig().set(BasicParserSettings.VERIFY_URI_SYNTAX, true);
		Trace trace = attachTrace(parser);
		parse(parser, document.toString());
		assertEquals(expectedCalls, factory.calls);
		assertEquals(iris.size(), trace.statements.size());
		IdentityHashMap<Value, Boolean> identities = new IdentityHashMap<>();
		for (int i = 0; i < iris.size(); i++) {
			Statement statement = trace.statements.get(i);
			for (Value value : List.of(statement.getSubject(), statement.getPredicate(), statement.getObject(),
					statement.getContext())) {
				assertEquals(iris.get(i), value.stringValue());
				Boolean previous = identities.put(value, Boolean.TRUE);
				assertNull(previous, "Each occurrence must retain its factory-created value");
			}
		}
		assertEquals(4 * iris.size(), identities.size());

		// Equal hashes must not let an invalid IRI borrow a successful validation result.
		String valid = "urn:collision:$a";
		String invalid = "urn:collision:%B";
		assertEquals(valid.hashCode(), invalid.hashCode());
		Trace invalidTrace = attachTrace(parser);
		String warmLine = ("<" + valid + "> ").repeat(4) + ".\n";
		RDFParseException exception = assertThrows(RDFParseException.class,
				() -> parse(parser, warmLine.repeat(40) + "<" + invalid + "> <urn:p> <urn:o> <urn:g> ."));
		assertEquals(41, exception.getLineNumber());
		assertEquals(40, invalidTrace.statements.size());
		assertEquals(List.of("41:-1"), invalidTrace.errorLocations);
		assertTrue(invalidTrace.errors.get(0).contains("Illegal percent encoding"));
	}

	@Test
	void replacingFactoryDuringAParseAffectsRepeatedValuesImmediately() throws IOException {
		for (int successfulQuads : new int[] { 1, 40 }) {
			RecordingFactory first = new RecordingFactory();
			RecordingFactory second = new RecordingFactory();
			NQuadsParser parser = new NQuadsParser(first);
			List<Statement> statements = new ArrayList<>();
			parser.setRDFHandler(new AbstractRDFHandler() {
				@Override
				public void handleStatement(Statement statement) {
					statements.add(statement);
					if (statements.size() == successfulQuads) {
						parser.setValueFactory(second);
					}
				}
			});
			parse(parser, (QUAD + "\n").repeat(successfulQuads + 1));

			List<String> quadCalls = List.of("iri:urn:r", "iri:urn:r", "iri:urn:r", "iri:urn:r", "statement:4");
			List<String> firstCalls = new ArrayList<>();
			for (int i = 0; i < successfulQuads; i++) {
				firstCalls.addAll(quadCalls);
			}
			assertEquals(firstCalls, first.calls);
			assertEquals(quadCalls, second.calls);
			assertEquals(successfulQuads + 1, statements.size());
			assertNotSame(statements.get(0).getSubject(), statements.get(successfulQuads).getSubject());
		}
	}

	@Test
	void factoryFailureOnPreviouslyAcceptedIriIsReportedAndParserCanBeReused() throws IOException {
		for (int successfulQuads : new int[] { 1, 40 }) {
			IllegalArgumentException failure = new IllegalArgumentException("factory rejected repeated IRI");
			RecordingFactory factory = new RecordingFactory() {
				private int count;

				@Override
				public IRI createIRI(String iri) {
					if (++count == 4 * successfulQuads + 1) {
						throw failure;
					}
					return super.createIRI(iri);
				}
			};
			NQuadsParser parser = new NQuadsParser(factory);
			Trace trace = attachTrace(parser);
			RDFParseException exception = assertThrows(RDFParseException.class,
					() -> parse(parser, (QUAD + "\n").repeat(successfulQuads + 1)));
			assertSame(failure, exception.getCause());
			assertEquals(successfulQuads + 1, exception.getLineNumber());
			assertEquals(-1, exception.getColumnNumber());
			assertEquals(List.of((successfulQuads + 1) + ":-1:factory rejected repeated IRI"), trace.fatalErrors);
			assertEquals(successfulQuads, trace.statements.size());
			assertFalse(trace.events.contains("end"));

			Trace reused = attachTrace(parser);
			parse(parser, QUAD);
			assertEquals(1, reused.statements.size());
			assertEquals(List.of("start", "location:0:1", "location:1:1", "statement", "end"), reused.events);
		}
	}

	@Test
	void enablingVerificationDuringAParseDoesNotReuseUncheckedSyntax() throws IOException {
		for (int warmupQuads : new int[] { 0, 40 }) {
			NQuadsParser parser = new NQuadsParser();
			parser.getParserConfig().set(BasicParserSettings.VERIFY_URI_SYNTAX, warmupQuads > 0);
			Trace trace = new Trace() {
				@Override
				public void handleStatement(Statement statement) {
					super.handleStatement(statement);
					if (statements.size() == warmupQuads) {
						parser.getParserConfig().set(BasicParserSettings.VERIFY_URI_SYNTAX, false);
					} else if (statements.size() == warmupQuads + 1) {
						parser.getParserConfig().set(BasicParserSettings.VERIFY_URI_SYNTAX, true);
					}
				}
			};
			attachTrace(parser, trace);
			RDFParseException exception = assertThrows(RDFParseException.class,
					() -> parse(parser, (QUAD + "\n").repeat(warmupQuads) + INVALID_QUAD + "\n" + INVALID_QUAD));
			assertEquals(warmupQuads + 1, trace.statements.size());
			assertEquals(INVALID_IRI, trace.statements.get(warmupQuads).getSubject().stringValue());
			assertEquals(warmupQuads + 2, exception.getLineNumber());
			assertEquals(-1, exception.getColumnNumber());
			assertEquals(List.of((warmupQuads + 2) + ":-1"), trace.errorLocations);
			assertTrue(trace.errors.get(0).contains("Illegal percent encoding"));

			parser.getParserConfig().set(BasicParserSettings.VERIFY_URI_SYNTAX, false);
			Trace reused = attachTrace(parser);
			parse(parser, INVALID_QUAD);
			assertEquals(1, reused.statements.size());
			assertTrue(reused.errors.isEmpty());
		}
	}

	@Test
	void repeatedInvalidIrisKeepDiagnosticsAndInvalidLineRecovery() throws IOException {
		for (int warmupQuads : new int[] { 0, 40 }) {
			RecordingFactory factory = new RecordingFactory();
			NQuadsParser parser = new NQuadsParser(factory);
			parser.getParserConfig().set(BasicParserSettings.VERIFY_URI_SYNTAX, true);
			parser.getParserConfig().addNonFatalError(NTriplesParserSettings.FAIL_ON_INVALID_LINES);
			Trace trace = attachTrace(parser);
			String warmup = (QUAD + "\n").repeat(warmupQuads);
			parse(parser, warmup + INVALID_QUAD + "\n" + INVALID_QUAD + "\n" + TRIPLE);

			// Each failed line reports the URI error and the caught invalid-line error.
			String firstLocation = (warmupQuads + 1) + ":-1";
			String secondLocation = (warmupQuads + 2) + ":-1";
			assertEquals(List.of(firstLocation, firstLocation, secondLocation, secondLocation), trace.errorLocations);
			assertEquals(trace.errors.get(0), trace.errors.get(2));
			assertTrue(trace.errors.stream().allMatch(message -> message.contains("Illegal percent encoding")));
			assertEquals(warmupQuads + 1, trace.statements.size());
			List<String> expectedCalls = new ArrayList<>();
			for (int i = 0; i < warmupQuads; i++) {
				expectedCalls.addAll(List.of("iri:urn:r", "iri:urn:r", "iri:urn:r", "iri:urn:r", "statement:4"));
			}
			expectedCalls.addAll(List.of("iri:urn:s", "iri:urn:p", "iri:urn:o", "statement:3"));
			assertEquals(expectedCalls, factory.calls);
			assertEquals("end", trace.events.get(trace.events.size() - 1));

			NQuadsParser strict = new NQuadsParser();
			strict.getParserConfig().set(NTriplesParserSettings.FAIL_ON_INVALID_LINES, false);
			// N-Quads still throws unless this setting is also marked nonfatal.
			RDFParseException exception = assertThrows(RDFParseException.class,
					() -> parse(strict, warmup + "<urn:s> .\n" + TRIPLE));
			assertEquals(warmupQuads + 1, exception.getLineNumber());
		}
	}

	@Test
	void nonfatalUriValidationStillReportsEveryOccurrence() throws IOException {
		for (int warmupQuads : new int[] { 0, 40 }) {
			NQuadsParser parser = new NQuadsParser();
			parser.getParserConfig().set(BasicParserSettings.VERIFY_URI_SYNTAX, true);
			parser.getParserConfig().addNonFatalError(BasicParserSettings.VERIFY_URI_SYNTAX);
			Trace trace = new Trace();
			parser.setParseErrorListener(trace);
			// No handler: a failed nonfatal URI validation returns null rather than creating an invalid statement.
			parse(parser, (QUAD + "\n").repeat(warmupQuads) + INVALID_QUAD + "\n" + INVALID_QUAD);
			assertEquals(List.of((warmupQuads + 1) + ":-1", (warmupQuads + 2) + ":-1"), trace.errorLocations);
			assertEquals(trace.errors.get(0), trace.errors.get(1));
			assertTrue(trace.errors.get(0).contains("Illegal percent encoding"));
		}
	}

	@Test
	void protectedNullIriRetainsValidationAndFactoryFailurePathsAfterWarmup() {
		class DirectParser extends AbstractRDFParser {
			IRI create(String iri) {
				return createURI(iri);
			}

			@Override
			public RDFFormat getRDFFormat() {
				return RDFFormat.NQUADS;
			}

			@Override
			public void parse(InputStream input, String baseURI) {
				throw new UnsupportedOperationException();
			}

			@Override
			public void parse(Reader input, String baseURI) {
				throw new UnsupportedOperationException();
			}
		}

		// ParsedIRI may use an assertion or throw NPE, depending on JVM assertion settings.
		Throwable validationFailure = assertThrows(Throwable.class, () -> new ParsedIRI(null));
		for (int successfulChecks : new int[] { 0, 160 }) {
			DirectParser parser = new DirectParser();
			RecordingFactory factory = new RecordingFactory();
			parser.setValueFactory(factory);
			parser.getParserConfig().set(BasicParserSettings.VERIFY_URI_SYNTAX, true);
			Trace trace = new Trace();
			parser.setParseErrorListener(trace);
			for (int i = 0; i < successfulChecks; i++) {
				parser.create("urn:warm");
			}
			Throwable exception = assertThrows(Throwable.class, () -> parser.create(null));
			assertEquals(validationFailure.getClass(), exception.getClass());
			assertEquals(validationFailure.getStackTrace()[0].getClassName(),
					exception.getStackTrace()[0].getClassName());
			assertEquals(validationFailure.getStackTrace()[0].getMethodName(),
					exception.getStackTrace()[0].getMethodName());
			assertEquals(successfulChecks, factory.calls.size());
			assertTrue(trace.errors.isEmpty());
			assertTrue(trace.fatalErrors.isEmpty());

			parser.getParserConfig().set(BasicParserSettings.VERIFY_URI_SYNTAX, false);
			RDFParseException factoryFailure = assertThrows(RDFParseException.class, () -> parser.create(null));
			assertInstanceOf(NullPointerException.class, factoryFailure.getCause());
			assertEquals(successfulChecks + 1, factory.calls.size());
			assertEquals("iri:null", factory.calls.get(successfulChecks));
			assertEquals(1, trace.fatalErrors.size());
		}
	}

