		assertSame(failure, assertThrows(IOException.class, () -> parser.parse(failing, "")));
		assertFalse(failing.closed);
		assertEquals(List.of("start", "location:0:1"), trace.events);
		Trace reused = attachTrace(parser);
		parse(parser, TRIPLE);
		assertEquals(1, reused.statements.size());
		assertEquals("end", reused.events.get(reused.events.size() - 1));
